import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import * as conv from "../runtime/conv.ts";
import * as ast from "../ast/index.ts";
import * as parse from "./index.ts";

// Vectors are generated by ts/tools/gen-parse-tables-vectors (gen-tree-cases.ts writes the cases, the tree program writes the expected dumps from Go's real parse package).
// They cover the code that needs a whole tree: emoji replacement, tables (GFM and Protyle), kramdown IALs, block and file annotation references, and rich table cells
// (finalParseTableCellRich, ParseTableCellRich, the projection, the style protection and the nested inline transforms).

interface Case {
  opt: string;
  md: string;
}

const cases = JSON.parse(readFileSync(new URL("./testdata/tables_tree_cases.json", import.meta.url), "utf8")) as Case[];
const expected = readFileSync(new URL("./testdata/tables_tree_expected.txt", import.meta.url), "utf8").split("\n");

function options(opt: string): parse.Options {
  const o = parse.NewOptions();
  switch (opt) {
    case "emoji":
      o.Emoji = true;
      o.EmojiSite = "http://site";
      o.AliasEmoji.set("myimg", "a/b.png");
      o.AliasEmoji.set("site", "${emojiSite}/x");
      break;
    case "refs":
      o.BlockRef = true;
      o.FileAnnotationRef = true;
      o.KramdownSpanIAL = true;
      break;
    case "ial":
      o.KramdownBlockIAL = true;
      o.KramdownSpanIAL = true;
      break;
    case "protyle":
      o.KramdownBlockIAL = true;
      o.KramdownSpanIAL = true;
      o.ProtyleWYSIWYG = true;
      o.TextMark = true;
      o.BlockRef = true;
      o.FileAnnotationRef = true;
      break;
  }
  return o;
}

function dump(cs: Case): string[] {
  const lines: string[] = [];
  const tree = parse.Parse("", conv.BytesFromString(cs.md), options(cs.opt));
  ast.Walk(tree.Root!, (n: ast.Node, entering: boolean): ast.WalkStatus => {
    if (!entering) {
      return ast.WalkContinue;
    }
    let s = ast.NodeTypeString(n.Type) + " " + JSON.stringify(conv.StringFromBytes(n.Tokens ?? new Uint8Array(0)));
    if (null === n.Tokens) {
      s += " nil";
    }
    if (null !== n.KramdownIAL) {
      s += " ial=" + JSON.stringify(n.KramdownIAL);
    }
    if ("" !== n.TextMarkType) {
      s += " tm=" + n.TextMarkType + ":" + JSON.stringify(n.TextMarkTextContent) + ":" + JSON.stringify(n.TextMarkAHref) + ":" + JSON.stringify(n.TextMarkInlineMathContent);
    }
    if (ast.NodeTableCell === n.Type) {
      s += ` align=${n.TableCellAlign}`;
    }
    if (ast.NodeTable === n.Type) {
      s += ` aligns=[${n.TableAligns.join(" ")}]`;
    }
    if (null !== n.TableCellRich) {
      s += " rich=" + JSON.stringify(n.TableCellRich.Content);
    }
    lines.push(s);
    return ast.WalkContinue;
  });
  return lines;
}

test("trees of emoji, tables, kramdown IAL, references and rich table cells equal Go's", () => {
  ast.SetTesting(true);
  try {
    let pos = 0;
    assert.ok(cases.length >= 200);
    cases.forEach((cs, i) => {
      assert.equal(expected[pos], `== ${i} ${cs.opt}`);
      pos++;
      const got = dump(cs);
      assert.deepEqual(got, expected.slice(pos, pos + got.length), JSON.stringify(cs));
      pos += got.length;
    });
    assert.equal(pos, expected.length - 1); // the file ends with a newline
  } finally {
    ast.SetTesting(false);
  }
});
